export type ElementLocation = 'LEFT' | 'MIDDLE' | 'RIGHT' | 'RARE_EARTH';

export interface PeriodicElement {
	name: string;
	symbol: string;
	atomicNumber: number;
	period: number;
	group: number;
	location: ElementLocation;
	color: string;
}

// Game Store
export const gameStore = $state({
	startTime: 0,
	time: 0,
	previousTime: 0,
	timerIsRunning: false,
	paused: false,
	elementList: [] as PeriodicElement[],
	currentElementName: 'Press Timer To Start',
	currentElementLocation: 'LEFT' as ElementLocation,
	locationMode: false,
	selectedElementSet: [] as string[]
});

// Tournament Store
export const tournamentStore = $state({
	tournamentMode: false,
	currentActiveMatchId: null as number | null,
	tournamentData: {
		participants: ["Hydrogen", "Helium", "Lithium", "Beryllium", "Boron", "Carbon", "Nitrogen", "Oxygen"],
		stage: [{ id: 0, tournament_id: 0, name: "Periodic Table Championship", type: "single_elimination", settings: {} }],
		group: [{ id: 0, stage_id: 0, number: 1 }],
		round: [] as any[],
		match: [] as any[],
		contestant: [] as any[]
	}
});
